 46	    @Transactional
 47	    public Xzj27 createOrderBid(String email, Long productSizeId, int bidPrice) {
 48	        try {
 49	
 50	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
 51	
 52	
 53	            Xrd81 user = userQueryService.findByEmail(email);
 54	
 55	
 56	            Xdh20 productSize = productSizeQueryService.findById(productSizeId)
 57	                    .orElseThrow(() -> new Xrf10Exception("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));
 58	
 59	
 60	            Xdg64 order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);
 61	
 62	
 63	            Xzj27 orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);
 64	
 65	            return orderBid;
 66	        } catch (Exception e) {
 67	            handleOrderBidCreationException(e, "주문 입찰 생성");
 68	            return null;
 69	        }
 70	    }
