        super(Xbf54ErrorCode.PAYMENT_API_ERROR);
    }
    public Xbf54ApiException(String message) {
        super(Xbf54ErrorCode.PAYMENT_API_ERROR, message);
    }
    public Xbf54ApiException(Throwable cause) {
        super(Xbf54ErrorCode.PAYMENT_API_ERROR, cause);
    }
